from builder.live_pages import align_rows, page_fingerprint


def rows_name_their_pages(apps, schema_editor):
    """Rows served today came from the live version: name the page of each and
    remember how it looked, so every file starts out with its true colour."""
    Site = apps.get_model('builder', 'Site')
    PublishedPage = apps.get_model('builder', 'PublishedPage')
    sites = Site.objects.exclude(live_schema=None).only('id', 'live_schema', 'live_html')
    for site in sites.iterator():
        rows = list(PublishedPage.objects.filter(site_id=site.pk).order_by('position', 'pk').only('id', 'path'))
        page_ids = align_rows(site.live_schema, site.live_html, [{'path': row.path} for row in rows])
        pages = {page.get('id'): page for page in site.live_schema.get('pages', []) if isinstance(page, dict)}
        for row, page_id in zip(rows, page_ids):
            page = pages.get(page_id)
            if page is not None:
                PublishedPage.objects.filter(pk=row.pk).update(
                    page_id=page_id, fingerprint=page_fingerprint(site.live_schema, site.live_html, page),
                )


